//! The planet (milestone 2 of `docs/living-world.md`), shown with `--planet`: generated by
//! `worldgen::planet` in the background, then drawn as terrain chunks on the six cube faces
//! (meshed in the background with a level of detail following the camera, see [`mesh`]) and
//! water (see [`water`]), with the flat map's vegetation (see [`vegetation`]). The flat map
//! is gone (see `git log`).

mod camera;
mod grass;
mod inspect;
mod mesh;
mod nature;
mod river_profile;
mod vegetation;
mod water;

use std::{sync::Arc, time::Instant};

use bevy::{
    prelude::*,
    tasks::{AsyncComputeTaskPool, Task, futures::check_ready},
};
use worldgen::{
    planet::{PlanetSettings, generate_planet},
    planet_climate::{ClimateSettings, PlanetClimate, simulate},
    sphere::FACES,
    surface::PlanetSurface,
};

use crate::{
    AppState,
    shaders::{PlanetTerrainMaterial, PlanetTerrainShader, PlanetWaterMaterial},
};

/// Chunk side, in cells of the planet's grid.
pub const CHUNK_CELLS: usize = 64;
/// Maximum number of chunk meshes being built at once.
const MAX_MESH_TASKS: usize = 8;
/// A chunk is re-meshed when the camera moved by this fraction of its distance to the chunk
/// (and at least by this many world units).
const REMESH_MOVE_RATIO: f32 = 0.25;
const REMESH_MIN_MOVE: f32 = 4.;
/// The camera starts this many planet radii from the surface.
const START_DISTANCE: f32 = 2.6;

pub struct PlanetPlugin {
    pub seed: u128,
    /// Cells along a cube face edge.
    pub n: usize,
}

impl Plugin for PlanetPlugin {
    fn build(&self, app: &mut App) {
        let (seed, n) = (self.seed as u64, self.n);
        app.add_plugins((
            vegetation::PlanetVegetationPlugin,
            grass::PlanetGrassPlugin,
            inspect::InspectPlugin,
        ))
            .insert_resource(ClearColor(Color::srgb(0.01, 0.012, 0.02)))
            .add_systems(Startup, move |commands: Commands| start_generation(commands, seed, n))
            .add_systems(
                Update,
                (
                    finish_generation.run_if(in_state(AppState::Loading)),
                    (schedule_chunk_meshes, finish_chunk_meshes)
                        .chain()
                        .run_if(in_state(AppState::InGame)),
                    (camera::control, camera::apply, camera::follow_sun)
                        .chain()
                        .run_if(in_state(AppState::InGame)),
                ),
            )
            .add_systems(OnEnter(AppState::InGame), (spawn_planet, view_planet));
    }
}

/// The planet's surface, shared with the meshing tasks.
#[derive(Resource)]
pub struct PlanetWorld {
    pub surface: Arc<PlanetSurface>,
    /// The climate (for reports on the ground clicked).
    pub climate: Arc<PlanetClimate>,
    /// The sea wave field of each face (texture data), until the water is spawned.
    sea: Vec<Vec<u8>>,
}

#[derive(Resource)]
struct Generation(Task<(PlanetSurface, Vec<Vec<u8>>, PlanetClimate)>);

fn start_generation(mut commands: Commands, seed: u64, n: usize) {
    let task = AsyncComputeTaskPool::get().spawn(async move {
        let start = Instant::now();
        let planet = generate_planet(&PlanetSettings {
            seed,
            n,
            ..default()
        });
        let stage = Instant::now();
        let climate = simulate(&planet, &ClimateSettings::default());
        let climate_time = stage.elapsed();
        let stage = Instant::now();
        let surface = PlanetSurface::new(&planet, Some(&climate));
        info!("Climate in {climate_time:.1?}, surface in {:.1?}", stage.elapsed());
        let sea_start = Instant::now();
        let sea = water::sea_textures(&planet, &surface);
        info!("Sea wave field in {:.1?}", sea_start.elapsed());
        info!(
            "Planet generated in {:.1?} ({} cells, radius {:.0}): {:?}",
            start.elapsed(),
            surface.cells(),
            surface.radius,
            planet.timings
        );
        (surface, sea, climate)
    });
    commands.insert_resource(Generation(task));
}

fn finish_generation(
    mut commands: Commands,
    mut generation: ResMut<Generation>,
    mut next_state: ResMut<NextState<AppState>>,
) {
    let Some((surface, sea, climate)) = check_ready(&mut generation.0) else {
        return;
    };
    commands.remove_resource::<Generation>();
    commands.insert_resource(PlanetWorld {
        surface: Arc::new(surface),
        climate: Arc::new(climate),
        sea,
    });
    next_state.set(AppState::InGame);
}

/// A terrain chunk: a square of `CHUNK_CELLS` cells of a cube face, meshed relative to its
/// origin (the sea level point under its centre).
#[derive(Component, Clone, Copy)]
pub struct PlanetChunk {
    pub face: usize,
    /// Lowest cell coordinates covered (cell edges at half-integers: the chunk spans
    /// `min - 0.5 .. min - 0.5 + CHUNK_CELLS`).
    pub min: Vec2,
}

impl PlanetChunk {
    fn center(&self) -> Vec2 {
        self.min - 0.5 + CHUNK_CELLS as f32 / 2.
    }
}

/// Level of detail state of a chunk: the camera position its mesh was built for.
#[derive(Component, Default)]
struct ChunkState {
    built_for: Option<Vec3>,
}

/// A chunk mesh being built.
#[derive(Component)]
struct ChunkMeshTask {
    task: Task<Mesh>,
    camera: Vec3,
}

/// Material of the planet's terrain (`planet_terrain.wesl`).
#[derive(Resource)]
struct TerrainMaterial(Handle<PlanetTerrainMaterial>);

fn spawn_planet(
    mut commands: Commands,
    mut world: ResMut<PlanetWorld>,
    mut meshes: ResMut<Assets<Mesh>>,
    mut images: ResMut<Assets<Image>>,
    mut terrain_materials: ResMut<Assets<PlanetTerrainMaterial>>,
    mut water_materials: ResMut<Assets<PlanetWaterMaterial>>,
) {
    let sea = std::mem::take(&mut world.sea);
    let surface = &world.surface;
    let material = terrain_materials.add(PlanetTerrainMaterial {
        base: StandardMaterial {
            base_color: Color::WHITE,
            perceptual_roughness: 0.95,
            ..default()
        },
        extension: PlanetTerrainShader {
            tint: LinearRgba::WHITE,
            planet: Vec4::new(surface.radius, 0., 0., 0.),
            wind: Vec4::new(1., 0., 0., 0.),
        },
    });
    commands.insert_resource(TerrainMaterial(material));
    let chunks_per_side = surface.n.div_ceil(CHUNK_CELLS);
    for face in 0..FACES {
        for cz in 0..chunks_per_side {
            for cx in 0..chunks_per_side {
                let chunk = PlanetChunk {
                    face,
                    min: Vec2::new((cx * CHUNK_CELLS) as f32, (cz * CHUNK_CELLS) as f32),
                };
                let origin = surface.direction(face, chunk.center()) * surface.radius;
                commands.spawn((
                    Name::new(format!("planet chunk {face} {cx} {cz}")),
                    chunk,
                    ChunkState::default(),
                    Transform::from_translation(origin),
                    Visibility::default(),
                ));
            }
        }
    }
    water::spawn(&mut commands, surface, sea, &mut meshes, &mut images, &mut water_materials);
}

/// Look at the planet from orbit, with the planet camera; space has no atmosphere nor fog
/// (the flat map's assume a ground plane).
fn view_planet(
    mut commands: Commands,
    world: Res<PlanetWorld>,
    camera: Single<Entity, With<Camera3d>>,
) {
    let mut focus = Vec3::new(0., 0.35, 1.);
    let mut distance = world.surface.radius * START_DISTANCE;
    let mut pitch = None;
    let mut heading = None;
    // `UF_PLANET_CAMERA=longitude,latitude[,distance[,pitch[,heading]]]` (degrees, world
    // units): the starting view, for screenshots (clicks log the current one).
    if let Ok(view) = std::env::var("UF_PLANET_CAMERA") {
        let values: Vec<f32> = view.split(',').filter_map(|v| v.trim().parse().ok()).collect();
        if let [longitude, latitude, ..] = values[..] {
            let (longitude, latitude) = (longitude.to_radians(), latitude.to_radians());
            focus = Vec3::new(
                latitude.cos() * longitude.cos(),
                latitude.sin(),
                latitude.cos() * longitude.sin(),
            );
        }
        if let [_, _, d, ..] = values[..] {
            distance = d;
        }
        if let [_, _, _, p, ..] = values[..] {
            pitch = Some(p.to_radians());
        }
        if let [_, _, _, _, h] = values[..] {
            heading = Some(h.to_radians());
        }
    }
    camera::take_over(&mut commands, *camera, focus, distance, pitch, heading);
}

/// Start meshing the chunks that need it (no mesh yet, or the camera moved), nearest first.
fn schedule_chunk_meshes(
    mut commands: Commands,
    world: Res<PlanetWorld>,
    camera: Single<&Transform, With<Camera3d>>,
    chunks: Query<(Entity, &PlanetChunk, &ChunkState, &Transform), Without<ChunkMeshTask>>,
    running: Query<(), With<ChunkMeshTask>>,
) {
    let available = MAX_MESH_TASKS.saturating_sub(running.iter().len());
    if available == 0 {
        return;
    }
    let camera = camera.translation;
    let mut candidates: Vec<(f32, Entity, PlanetChunk, Vec3)> = chunks
        .iter()
        .filter_map(|(entity, chunk, state, transform)| {
            let distance = mesh::distance_to_chunk(&world.surface, chunk, camera);
            let moved = state.built_for.is_none_or(|built_for| {
                built_for.distance(camera) > (distance * REMESH_MOVE_RATIO).max(REMESH_MIN_MOVE)
            });
            moved.then_some((distance, entity, *chunk, transform.translation))
        })
        .collect();
    candidates.sort_by(|a, b| a.0.total_cmp(&b.0));
    for (_, entity, chunk, origin) in candidates.into_iter().take(available) {
        let surface = world.surface.clone();
        let task = AsyncComputeTaskPool::get()
            .spawn(async move { mesh::build_chunk_mesh(&surface, &chunk, origin, camera) });
        commands.entity(entity).insert(ChunkMeshTask { task, camera });
    }
}

fn finish_chunk_meshes(
    mut commands: Commands,
    material: Res<TerrainMaterial>,
    mut meshes: ResMut<Assets<Mesh>>,
    mut chunks: Query<(Entity, &mut ChunkState, &mut ChunkMeshTask, Option<&Mesh3d>)>,
) {
    for (entity, mut state, mut task, mesh3d) in &mut chunks {
        let Some(mesh) = check_ready(&mut task.task) else {
            continue;
        };
        match mesh3d {
            Some(mesh3d) => {
                if let Err(error) = meshes.insert(&mesh3d.0, mesh) {
                    warn!("Could not replace a planet chunk mesh: {error}");
                }
            }
            None => {
                commands
                    .entity(entity)
                    .insert((Mesh3d(meshes.add(mesh)), MeshMaterial3d(material.0.clone())));
            }
        }
        state.built_for = Some(task.camera);
        commands.entity(entity).remove::<ChunkMeshTask>();
    }
}
